import { Component, OnInit, ViewChild } from '@angular/core';
import { FormBuilder, FormControl, FormGroup } from '@angular/forms';
import { Router } from '@angular/router';
import { UserSessionService } from 'src/app/services/usersession.service';
import { AlertController, IonSelect, ModalController } from '@ionic/angular';
import { SqlitedatabaseService } from 'src/app/services/sqlite/sqlitedatabase.service';
import { PmoaService } from 'src/app/services/emis/pmoa.services';
import { AlertService } from 'src/app/services/alert.service';
// import { SqlitedatabaseService } from 'src/app/services/sqlitedatabase.service';

@Component({
  selector: 'app-school-list',
  templateUrl: './school-list.page.html',
  styleUrls: ['./school-list.page.scss'],
})
export class SchoolListPage implements OnInit {

  @ViewChild('mySelect', { static: false }) selectRef: IonSelect;
  form: FormGroup;
  blockData: string;

  blockList: any[];
  schoolList: any[];

  //search
  searchTerm: any;
  searchData: any[];
  userId: string;
  districtId: any[];
  totalBlocklist: number;
  widgetsCard: boolean = false;
  username: any;
  useriddata: any;
  completedschool: any;
  completeTeacher: number;
  schoolData: boolean;

  totalstds:number = 0;
  notRec:number = 0;
  verifiedRecd:number = 0;
  defRet:number = 0;
  corVerifiedRecd:number = 0;
  toBeVerified:number = 0;

  constructor(
    private router: Router, private fb: FormBuilder,
    private healthServices: PmoaService,
    private usersessionService: UserSessionService,
    private alertController: AlertController,
    public modalController: ModalController,
    private sqliteDB: SqlitedatabaseService,
    private alertService: AlertService,

  ) {
    this.userId = this.usersessionService.usertype();
    this.username = this.usersessionService.username();
    this.useriddata = this.usersessionService.user_id();
    debugger
  }

  ngOnInit() {
    this.initialValidator();
  }

  ionViewDidEnter() {
    // this.checkLocalExistSchoolList();
        this.getSchoolData();  // From Server
  }

  initialValidator() {
    this.form = this.fb.group({
      district: new FormControl(this.useriddata),
      block: new FormControl('', null)
    });
  }

  //back
  navigateBack() {
    this.router.navigate(['/tabs/home']);
  }

  //next
  nextPage(SchoolId, SchoolName) {
    this.router.navigate(['/tabs/spectacel-class-list'], {
      queryParams: { SchoolId, SchoolName }
    });
  }

  onSync() {
    let query = 'DELETE FROM SchoolLists' +
    ' WHERE BlockId = "' + this.useriddata + '"';
    this.sqliteDB.executeQuery(query).then(res => {
      if (res) {
        this.getSchoolData();
      }
    });
  }

  // Check Local Data Exist Method_________________________________________________________________________________*
  checkLocalExistSchoolList() {
    this.blockData = this.userId
    this.sqliteDB.checkDataExistsWithConditions('SchoolLists', "BlockId", this.useriddata).then((res) => {
      if (res == true) {
        console.log("local")
        // this.getSchoolLocalDB(); // Local Data
        this.getSchoolData();  // From Server

      }
      else {
        this.getSchoolData();  // From Server
        console.log("server")
      }
    });
  }

  //school data
  getSchoolData() {
    this.widgetsCard = true;
    this.healthServices.PMOASchlListByBlkId().subscribe((response) => {
      if (response.dataStatus) {
        this.schoolList = []
        this.searchData = []
        this.schoolList = response.result;
        this.searchData = response.result;
        this.schoolData = true

        if (response.result.length > 0) {
          // response.result.forEach(element => {
          //   this.saveSchoolLocalDB(element);

          // });
          // this.getSchoolLocalDB();
        }
        this.calcSchSpectacles();
        this.totalBlocklist = 0
        this.totalBlocklist = response.result.length;
      } else {
        this.alertService.warning(response.message);
      }
      // this.getSchoolCount(this.totalBlocklist)

    })
  }

  calcSchSpectacles() {
    this.totalstds = 0;
    this.notRec = 0;
    this.verifiedRecd = 0;
    this.defRet = 0;
    this.corVerifiedRecd = 0;
    this.toBeVerified = 0;
    for(let i=0;i<this.schoolList.length;i++) {
      this.totalstds = this.totalstds +(parseInt(this.schoolList[i].total_students));
      this.notRec = this.notRec + Number(this.schoolList[i].status1);
      this.verifiedRecd = this.verifiedRecd + Number(this.schoolList[i].status2);
      this.defRet = this.defRet + Number(this.schoolList[i].status3);
      this.corVerifiedRecd = this.corVerifiedRecd + Number(this.schoolList[i].status4);
      this.toBeVerified = this.toBeVerified + Number(this.schoolList[i].to_be_verified) 
    }
  }

  saveSchoolLocalDB(element) {
    const datainsert = 'INSERT INTO SchoolLists VALUES (?,?,?,?,?)';
    this.sqliteDB.insert(datainsert, [null, element.BlockId, element.CompletedByDr, element.SchoolId, element.SchoolName]).then(insertres => {
      if (insertres) {
        console.log('School data info inserted');
      }
    });
  }

  getSchoolLocalDB() {
    this.widgetsCard = true;
    let query = 'SELECT * FROM SchoolLists' +
      ' WHERE BlockId = "' + this.useriddata + '"';
    return this.sqliteDB.getDataLocalDB(query).then(data => {
      if (data.rows.length > 0) {
        this.schoolList = [];
        this.searchData = [];
        for (var i = 0; i < data.rows.length; i++) {
          this.schoolList.push(data.rows.item(i));
          this.searchData.push(data.rows.item(i));
          this.schoolData = true
        }
        this.totalBlocklist = 0
        this.totalBlocklist = data.rows.length
        // this.getSchoolCount(this.totalBlocklist)
      }
    });
  }

  // widget count
  getSchoolCount(schCount) {
    this.healthServices.getTotalCont(this.useriddata).subscribe((response) => {
      this.completedschool = response.result[0].Count;
      this.completeTeacher = schCount - this.completedschool
    })
  }

  // searching data 
  getFilterItems(event) {
    this.searchData = [];
    this.searchTerm = event.detail.value.trim();
    this.searchData = this.schoolList.filter((item) => {
      return item.SchoolName.toLowerCase().indexOf(this.searchTerm.toLowerCase()) > -1;
    });
  }

}
